import json
# Let me search for ALL messages with keywords like "strengths" or "weaknesses" in PersonalizeForce data
with open('DATA/products/PersonalizeForce.json') as f:
    data = json.load(f)

all_messages = data['slack']
print(f'Total messages: {len(all_messages)}')
print()

# Search for messages with substantive competitor content
people_with_competitor_insights = {}
for i, msg in enumerate(all_messages):
    text = msg.get('Message', {}).get('User', {}).get('text', '') or ''
    user_id = msg.get('Message', {}).get('User', {}).get('userId', '')

    if not text or 'slack_admin_bot' in user_id:
        continue

    # Heuristic: meaningful content about competitor product's strengths/weaknesses
    competitor_mentions = []
    for competitor in ['TailorAI', 'PersonaAI', 'SmartSuggest']:
        if competitor in text:
            competitor_mentions.append(competitor)

    has_strengths = 'strength' in text.lower() and any(c in text for c in ['TailorAI', 'PersonaAI', 'SmartSuggest', 'they', 'their', 'its', ' it '])
    has_weaknesses = 'weakness' in text.lower() or 'struggle' in text.lower() or 'barrier' in text.lower() or 'limitation' in text.lower()

    if competitor_mentions:
        if user_id not in people_with_competitor_insights:
            people_with_competitor_insights[user_id] = []
        people_with_competitor_insights[user_id].append((i, competitor_mentions, has_strengths, has_weaknesses, text[:300]))

for user_id, entries in people_with_competitor_insights.items():
    print(f'=== {user_id} ===')
    for i, comp, has_str, has_weak, text in entries:
        flags = []
        if has_str: flags.append('STRENGTHS')
        if has_weak: flags.append('WEAKNESSES')
        print(f'  [{i}] [{",".join(comp)}] {",".join(flags)}: {text[:200]}')
    print()
EOF

